INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7498659, 1194948, 179608, '<td valign="top">my favourite for this challenge</td>', 'my favourite for this challenge', '2017-02-13 06:07:01.000000', NULL, 0),
(7498660, 1194891, 118154, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by gintay:</b></div><hr/><i> Congratulations on your BLUE Ribbon!  Great atmosphere &amp; mood. </i></td></tr></table> <br/> <br/>Do you know something ?</td>', 'Originally posted by gintay: Congratulations on your BLUE Ribbon!  Great atmosphere & mood.   Do you know something ?', '2017-02-13 06:08:55.000000', NULL, 0),
(7498661, 1194900, 118154, '<td valign="top">Is it snow or is it the noise a 7D produces ?</td>', 'Is it snow or is it the noise a 7D produces ?', '2017-02-13 06:11:49.000000', NULL, 0),
(7498662, 1194900, 118154, '<td valign="top">Nice image by the way. :)</td>', 'Nice image by the way. :)', '2017-02-13 06:12:24.000000', NULL, 0),
(7498668, 1194863, 50641, '<td valign="top">Your yin yang is well balanced, and quite bluish. Happy dampness and congrats!</td>', 'Your yin yang is well balanced, and quite bluish. Happy dampness and congrats!', '2017-02-13 07:42:18.000000', NULL, 0),
(7498669, 1194935, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that contributes well to the challenge<br/> <br/>Congratulations Janine, a great result for a great image, very deserving. Thats a very complimentary remark from bmartuch but hes right it does have a feel of the master about it. The mono conversion and exposure are the hallmarks of his work and whilst this doesnt have the full range of tones you expect to see in his work it is a very good effort. My only minor criticism would be to crop off the bottom darker foreground, I think the whiter base of snow would be better.</td>', 'Hello from the critique club An appealing image that contributes well to the challenge Congratulations Janine, a great result for a great image, very deserving. Thats a very complimentary remark from bmartuch but hes right it does have a feel of the master about it. The mono conversion and exposure are the hallmarks of his work and whilst this doesnt have the full range of tones you expect to see in his work it is a very good effort. My only minor criticism would be to crop off the bottom darker foreground, I think the whiter base of snow would be better.', '2017-02-13 07:56:55.000000', NULL, 0),
(7498672, 1194824, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An appealing image that contributes well to the challenge<br/> <br/>Brr.., it looks very cold there! I like your composition including the nicely curved tracks in the foreground, what I dont like is everything going on in the background. Im viewing this on my screen with the top cropped where the shadows start and Im liking the image much more, it has a much more isolated feel to it which is entirely appropriate for the scene. Your commenter is right it would be impossible to tell what they are doing without the title which proves the value of the right title. Thanks for sharing Marcel</td>', 'Hello from the critique club An appealing image that contributes well to the challenge Brr.., it looks very cold there! I like your composition including the nicely curved tracks in the foreground, what I dont like is everything going on in the background. Im viewing this on my screen with the top cropped where the shadows start and Im liking the image much more, it has a much more isolated feel to it which is entirely appropriate for the scene. Your commenter is right it would be impossible to tell what they are doing without the title which proves the value of the right title. Thanks for sharing Marcel', '2017-02-13 08:05:03.000000', NULL, 0),
(7498675, 1194740, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that contributes to the challenge<br/> <br/>This is a very competent cityscape, a nice composition enhanced by the moving clouds in the sky. I like the foreground reflection of the trees but I think there is a good argument for removal of the bright lights reflected, it would be more pleasing without them. I like the silver birch bark and their shapes it makes the foreground more interesting. Im not keen on the colour balance I would prefer it tweaked to something more natural looking. What your image does not do well is to convey the challenge theme of weather, your title is necessary to help us appreciate it is cold. As you will see from the front page most of the images there convey a particular aspect of the weather.</td>', 'Hello from the critique club An interesting image that contributes to the challenge This is a very competent cityscape, a nice composition enhanced by the moving clouds in the sky. I like the foreground reflection of the trees but I think there is a good argument for removal of the bright lights reflected, it would be more pleasing without them. I like the silver birch bark and their shapes it makes the foreground more interesting. Im not keen on the colour balance I would prefer it tweaked to something more natural looking. What your image does not do well is to convey the challenge theme of weather, your title is necessary to help us appreciate it is cold. As you will see from the front page most of the images there convey a particular aspect of the weather.', '2017-02-13 08:16:57.000000', NULL, 0),
(7498677, 1194797, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that contributes to the challenge<br/> <br/>What an interesting building Drake. You have captured a lovely skyscape dominated by the bright red building, it is an interesting scene but I have to agree with your commenters, the saturation is too much it has marred the scene. I also think your composition could be significantly improved. Im looking at the scene with the image cropped at the start of the foreground shadows, this improves it significantly. Also if you were to crop it removing the mooring post on the structure it would move the building over to the left and again significantly improve the overall end result.</td>', 'Hello from the critique club An interesting image that contributes to the challenge What an interesting building Drake. You have captured a lovely skyscape dominated by the bright red building, it is an interesting scene but I have to agree with your commenters, the saturation is too much it has marred the scene. I also think your composition could be significantly improved. Im looking at the scene with the image cropped at the start of the foreground shadows, this improves it significantly. Also if you were to crop it removing the mooring post on the structure it would move the building over to the left and again significantly improve the overall end result.', '2017-02-13 08:25:59.000000', NULL, 0),
(7498678, 1194937, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that contributes to the challenge<br/> <br/>A lovely soothing tranquil scene. You have identified some of the problems as has one of your commenters too so yes youre right its probably better not to have too much resolution here. What Im most troubled with is the sloping sea! There is a definite lean to the left which is not helped by the right shoreline which feels as though its pushing the whole image. In terms of the challenge theme it would work better if there were specific conditions being portrayed, a look at the front page will perhaps convey my meaning better. As always Eugene, an interesting image but it doesnt quite work as well as it could.</td>', 'Hello from the critique club An interesting image that contributes to the challenge A lovely soothing tranquil scene. You have identified some of the problems as has one of your commenters too so yes youre right its probably better not to have too much resolution here. What Im most troubled with is the sloping sea! There is a definite lean to the left which is not helped by the right shoreline which feels as though its pushing the whole image. In terms of the challenge theme it would work better if there were specific conditions being portrayed, a look at the front page will perhaps convey my meaning better. As always Eugene, an interesting image but it doesnt quite work as well as it could.', '2017-02-13 08:36:40.000000', NULL, 0),
(7498679, 1194889, 25024, '<td valign="top">Hello from the critique club<br/> <br/>An interesting image that contributes to the challenge<br/> <br/>This is certainly a colourful sunset cityscape youve captured Gin Tay. In terms of composition, I think you could have made it more interesting by excluding the buildings on the left, I would have cropped it to remove all the buildings from the left where the foreground building is. I would then have lowered the rest of the scene so that the interesting shapes and lights were much lower in the frame giving emphasis to the sunset sky. Hope this helps.</td>', 'Hello from the critique club An interesting image that contributes to the challenge This is certainly a colourful sunset cityscape youve captured Gin Tay. In terms of composition, I think you could have made it more interesting by excluding the buildings on the left, I would have cropped it to remove all the buildings from the left where the foreground building is. I would then have lowered the rest of the scene so that the interesting shapes and lights were much lower in the frame giving emphasis to the sunset sky. Hope this helps.', '2017-02-13 08:47:07.000000', NULL, 0),
